class Solution:
    def sortList(self, head: Optional[ListNode]) -> Optional[ListNode]:
        vals, node = [], head
        while node:
            vals.append(node.val)
            node = node.next
        node = head
        for v in sorted(vals):
            node.val = v
            node = node.next
        return head

